(function(root){
'use strict';
function hash(seed,role){let value=(Number(seed)>>>0)^2166136261;for(const c of role)value=Math.imul(value^c.charCodeAt(0),16777619);value^=value>>>16;return value>>>0;}
function identity(s){const take=(role,n)=>hash(s.seed,role)%n,motherSkin=take('mother-skin',5),fatherSkin=take('father-skin',5),childSkin=Math.round((motherSkin+fatherSkin)/2);const actor=(role,profile,skin)=>({profile,skin,hairColor:role==='grandmother'?3:[0,1,2,4][take(role+'-hair',4)],hairStyle:profile.endsWith('_m')?'short':take(role+'-style',2)?'bob':'short',head:take(role+'-face',2)?'sitting':'standing',top:take(role+'-top',4),bottom:take(role+'-bottom',3),mouth:'soft',fatigue:0,pose:'standing',seatId:null});return {mother:actor('mother','adult_f',motherSkin),father:actor('father','adult_m',fatherSkin),grandmother:actor('grandmother','elder_f',motherSkin),self:actor('self',s.origin?.sex==='male'?'adult_m':'adult_f',childSkin)};}
function defaults(s){const config=root.LifelineAssetCore.defaultState(),who=identity(s).self;for(const a of Object.values(config.actors))Object.assign(a,{skin:who.skin,hairColor:who.hairColor,head:who.head,top:who.top,bottom:who.bottom,hairStyle:root.LifelineAssetCore.playerHairStyle(a.profile,who.hairStyle)});return config;}
function storageKey(s){return 'lifeline-family-appearance-v1:'+(s.seed>>>0);}
function actor(s,role,manifest){const base=identity(s)[role];if(!base)throw Error('Unknown family role');if(role==='self')return {...root.LifelineGameArt.settings(s,manifest,root.localStorage).actors[base.profile],profile:base.profile};let saved={};try{saved=JSON.parse(root.localStorage.getItem(storageKey(s))||'{}')[role]||{};}catch{}const out={...base};for(const [key,length]of [['skin',5],['hairColor',5],['top',4],['bottom',3]])if(Number.isInteger(saved[key])&&saved[key]>=0&&saved[key]<length)out[key]=saved[key];if(['standing','sitting'].includes(saved.head))out.head=saved.head;if(root.LifelineAssetCore.availableHairStyles(base.profile).includes(saved.hairStyle))out.hairStyle=saved.hairStyle;if(root.LifelineAssetCore.MOUTHS.includes(saved.mouth))out.mouth=saved.mouth;if(root.LifelineHumanV12){const t={};if(Number.isInteger(saved.face)&&saved.face>=0&&saved.face<4)t.face=saved.face;if(Number.isInteger(saved.outfit)&&saved.outfit>=0&&saved.outfit<(base.profile.endsWith('_m')?3:6))t.outfit=saved.outfit;if(Number.isInteger(saved.shoes)&&saved.shoes>=0&&saved.shoes<3)t.shoes=saved.shoes;if(Object.hasOwn(root.LifelineHumanV12.BASES,saved.base||''))t.base=saved.base;const hair=base.profile.endsWith('_m')?['short','compact_coils','tousled','none']:['short','bob','compact_coils','tousled','long_straight','long_sleek','long_curly','single_braid','ponytail','bun','braids'];if(hair.includes(saved.hair))t.hair=saved.hair;if(Object.keys(t).length)out.humanTraits=t;}return out;}
function setActor(s,role,value,manifest){if(!['mother','father','grandmother'].includes(role))throw Error('Unknown parent');let saved={};try{saved=JSON.parse(root.localStorage.getItem(storageKey(s))||'{}');}catch{}saved[role]={...saved[role],...actor(s,role,manifest),...value};root.localStorage.setItem(storageKey(s),JSON.stringify(saved));return actor(s,role,manifest);}
function markup(s,role){const name=role==='self'?s.origin?.name:s.family?.[role]?.name||'';const label=String(root.LifelineRussian?.text(name)||name||'Персонаж').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return '<span class="family-art-avatar" data-family-avatar="'+role+'"><canvas width="256" height="256" role="img" aria-label="'+label+'" hidden></canvas><span class="family-art-status" aria-hidden="true">'+label.slice(0,1)+'</span></span>';}
function personMarkup(person){if(!person)return '';const data=JSON.stringify({name:person.name,age:person.age,sex:person.sex}).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));return '<span class="family-art-avatar person-art-avatar" data-person-avatar="'+data+'"><canvas width="256" height="256" role="img" aria-label="Аватар персонажа" hidden></canvas><span class="family-art-status" aria-hidden="true">…</span></span>';}
async function personPortrait(person,seed){const C=root.LifelineHumanV12,{art}=await root.LifelineHumanGame.load(),cl=person.name?.cl,bases={ru:'slavic',zh:'east_asian',ja:'east_asian',ko:'east_asian',hi:'south_asian',ar:'middle_eastern',sw:'african',pt:'latin_american',es:'latin_american'},c=C.preset(bases[cl]||'european',hash(seed,'person:'+person.name?.full),Math.max(1,person.age||18)*12,person.sex==='M'?'male':'female');return art.portrait(c);}
async function mount(host,s){await Promise.all([...host.querySelectorAll('[data-person-avatar]')].map(async node=>{try{const person=JSON.parse(node.dataset.personAvatar),image=await personPortrait(person,s.seed);if(!node.isConnected)return;const canvas=node.querySelector('canvas');canvas.getContext('2d').drawImage(image,0,0,256,256);canvas.hidden=false;node.querySelector('.family-art-status').hidden=true;node.dataset.avatarReady='true';}catch{node.dataset.avatarError='true';}}));const nodes=[...host.querySelectorAll('[data-family-avatar]')];if(!nodes.length)return;const identities=identity(s);try{const {manifest,art}=await root.LifelineGameArt.load(),config=root.LifelineGameArt.settings(s,manifest,root.localStorage);await Promise.all(nodes.map(async node=>{const token=Symbol();node.avatarToken=token;const role=node.dataset.familyAvatar,who=actor(s,role,manifest),canvas=node.querySelector('canvas'),status=node.querySelector('.family-art-status'),x=canvas.getContext('2d');let image;
 if(root.LifelineHumanGame){image=await root.LifelineHumanGame.portrait(s,who,role);if(!node.isConnected||node.avatarToken!==token)return;x.clearRect(0,0,256,256);x.drawImage(image,0,0,256,256);canvas.hidden=false;status.hidden=true;node.dataset.avatarReady='true';return;}
 const a={...config.actors[who.profile],...who,pose:'standing',fatigue:0};image=await art.actor(who.profile,a);if(!node.isConnected||node.avatarToken!==token)return;const [hx,hy,hw,hh]=manifest.profiles[who.profile].poses.standing.headRect,top=Math.max(0,hy-hh*.15),size=hh*1.8,left=hx+hw/2-size/2;x.clearRect(0,0,256,256);x.drawImage(image,left,top,size,size,0,0,256,256);
 canvas.hidden=false;status.hidden=true;node.dataset.avatarReady='true';}));}catch{for(const node of nodes)node.dataset.avatarError='true';}}
const api={personMarkup,personPortrait,identity,defaults,storageKey,actor,setActor,markup,mount};root.FamilyAppearance=api;if(typeof module!=='undefined')module.exports=api;
})(typeof window!=='undefined'?window:globalThis);
